<?php
require_once __DIR__ . '/../lib.php';
require_once __DIR__ . '/../../public/db_connect.php';  header('Content-Type: application/json; charset=utf-8');  try {  require_login();  $me = current_user();  $station_id = user_station_id();  $role = role_key($me['role'] ?? '');  if (!in_array($role, ['staff', 'cashier', 'pump_attendant'], true)) {  throw new RuntimeException('Access denied. Staff role required.');  }  $debug = [  'station_id' => (int)$station_id,  'fuel_count' => 0,  'merchandise_count' => 0,  'messages' => [],  ];  $fuel_options = [];  try {  $stmt = $pdo->prepare("  SELECT  fi.fuel_type,  COALESCE(last_tx.present_reading, 0) AS previous_reading,  fi.current_level,  COALESCE(fi.latest_calibration, 0) AS calibration,  COALESCE(fi.price_per_liter, si.price, si.cost, ip.unit_cost, 0) AS price_per_liter  FROM fuel_inventory fi  LEFT JOIN (  SELECT ft.station_id, ft.fuel_type, ft.present_reading  FROM fuel_transactions ft  INNER JOIN (  SELECT station_id, fuel_type, MAX(transaction_date) AS latest_transaction_date  FROM fuel_transactions  GROUP BY station_id, fuel_type  ) latest  ON latest.station_id = ft.station_id  AND latest.fuel_type = ft.fuel_type  AND latest.latest_transaction_date = ft.transaction_date  ) last_tx  ON last_tx.station_id = fi.station_id  AND LOWER(TRIM(last_tx.fuel_type)) = LOWER(TRIM(fi.fuel_type))  LEFT JOIN inventory_products ip  ON LOWER(TRIM(ip.product_name)) = LOWER(TRIM(fi.fuel_type))  AND ip.category = 'Fuel'  LEFT JOIN station_inventory si  ON si.station_id = fi.station_id  AND si.product_id = ip.id  WHERE fi.station_id = ?  AND COALESCE(fi.current_level, 0) > 0  ORDER BY fi.fuel_type  ");  $stmt->execute([$station_id]);  $fuel_options = $stmt->fetchAll(PDO::FETCH_ASSOC) ?: [];  } catch (Throwable $e) {  $debug['messages'][] = 'Fuel query failed: ' . $e->getMessage();  }  if (!$fuel_options) {  try {  $stmt = $pdo->prepare("  SELECT  ip.product_name AS fuel_type,  0 AS previous_reading,  si.stock_level AS current_level,  0 AS calibration,  COALESCE(si.price, si.cost, ip.unit_cost, 0) AS price_per_liter  FROM station_inventory si  INNER JOIN inventory_products ip  ON ip.id = si.product_id  AND ip.category = 'Fuel'  WHERE si.station_id = ?  AND COALESCE(si.stock_level, 0) > 0  AND COALESCE(si.status, 'active') = 'active'  ORDER BY ip.product_name  ");  $stmt->execute([$station_id]);  $fuel_options = $stmt->fetchAll(PDO::FETCH_ASSOC) ?: [];  } catch (Throwable $e) {  $debug['messages'][] = 'Fuel fallback query failed: ' . $e->getMessage();  }  }  $merchandise_options = [];  try {  $stmt = $pdo->prepare("  SELECT  ip.id AS product_id,  ip.product_name,  COALESCE(NULLIF(ip.sku, ''), ip.product_name) AS sku,  COALESCE(ip.category, 'General') AS category,  COALESCE(NULLIF(ip.size, ''), NULLIF(si.unit, ''), '') AS size,  COALESCE(si.price, si.cost, ip.unit_cost, 0) AS unit_price,  COALESCE(si.stock_level, 0) AS stock_level  FROM station_inventory si  INNER JOIN inventory_products ip  ON ip.id = si.product_id  WHERE si.station_id = ?  AND COALESCE(si.stock_level, 0) > 0  AND COALESCE(si.status, 'active') = 'active'  AND COALESCE(ip.category, '') <> 'Fuel'  ORDER BY COALESCE(ip.category, 'General'), ip.product_name  ");  $stmt->execute([$station_id]);  $merchandise_options = $stmt->fetchAll(PDO::FETCH_ASSOC) ?: [];  } catch (Throwable $e) {  $debug['messages'][] = 'Merchandise query failed: ' . $e->getMessage();  }  if (!$merchandise_options) {  try {  $stmt = $pdo->prepare("  SELECT  p.id AS product_id,  p.name AS product_name,  COALESCE(NULLIF(p.sku, ''), p.name) AS sku,  COALESCE(pc.name, 'General') AS category,  COALESCE(NULLIF(p.unit, ''), NULLIF(si.unit, ''), '') AS size,  COALESCE(si.price, p.price, si.cost, p.cost, 0) AS unit_price,  COALESCE(si.stock_level, 0) AS stock_level  FROM station_inventory si  INNER JOIN products p  ON p.id = si.product_id  LEFT JOIN product_categories pc  ON pc.id = p.category_id  WHERE si.station_id = ?  AND COALESCE(si.stock_level, 0) > 0  AND COALESCE(si.status, 'active') = 'active'  AND p.type_id = 2  ORDER BY COALESCE(pc.name, 'General'), p.name  ");  $stmt->execute([$station_id]);  $merchandise_options = $stmt->fetchAll(PDO::FETCH_ASSOC) ?: [];  } catch (Throwable $e) {  $debug['messages'][] = 'Merchandise fallback query failed: ' . $e->getMessage();  }  }  $debug['fuel_count'] = count($fuel_options);  $debug['merchandise_count'] = count($merchandise_options);  if (!$fuel_options) {  $debug['messages'][] = 'No fuel options found for the current station.';  }  if (!$merchandise_options) {  $debug['messages'][] = 'No merchandise options found for the current station.';  }  echo json_encode([  'success' => true,  'fuel_options' => $fuel_options,  'merchandise_options' => $merchandise_options,  'debug' => $debug,  ]);
} catch (Throwable $e) {  http_response_code(500);  echo json_encode([  'success' => false,  'error' => $e->getMessage(),  ]);
}
?>